def train_test_split(xs, ratio):
    n = int(len(xs) * ratio)
    return xs[:n], xs[n:]

def minmax(xs):
    lo, hi = min(xs), max(xs)
    if hi == lo:
        return [0.0 for _ in xs]
    return [(x - lo) / (hi - lo) for x in xs]

import math

def standardize(xs):
    m = sum(xs) / len(xs)
    var = sum((x - m) ** 2 for x in xs) / len(xs)
    if var == 0:
        return [0.0 for _ in xs]
    sd = math.sqrt(var)
    return [(x - m) / sd for x in xs]

